from (values
('RTN001','Say the good thing','Notice one thing they handled today that you would normally leave unspoken. Tell them you noticed.','Effort is easy to stop noticing when you see it every day. Saying it out loud brings it back into view.','DO',ARRAY['attention','appreciation','perceived_responsiveness']::text[],ARRAY['home','workday','anywhere']::text[],1,1,false,false,'high','high','{"routine":1,"closeness":0.7,"support":0.6}'::jsonb,ARRAY[1]::integer[],ARRAY[]::text[],'{"appreciation":1,"quality_attention":0.9,"support":0.55,"verbal_affection":0.55}'::jsonb),
('RTN002','Catch the autopilot','Pick one routine moment you usually do on autopilot. Watch what each of you does, and name the pattern privately to yourself.','You can change a routine more easily once you notice the exact moment it takes over.','NOTICE',ARRAY['attention','self_monitoring']::text[],ARRAY['home','anywhere']::text[],1,1,false,false,'high','medium','{"routine":1,"communication":0.3}'::jsonb,ARRAY[1]::integer[],ARRAY[]::text[],'{"quality_attention":0.9}'::jsonb),
('RTN003','One real follow-up','Ask one genuine follow-up question about something your partner tells you today before sharing your own story.','A real follow-up shows that you are still with them instead of waiting for your turn.','DO',ARRAY['curiosity','active_listening','perceived_responsiveness']::text[],ARRAY['home','walking','car','text_or_remote','anywhere']::text[],2,1,false,true,'high','high','{"routine":0.9,"communication":0.8,"closeness":0.6}'::jsonb,ARRAY[1]::integer[],ARRAY[]::text[],'{"curiosity":1,"emotional_conversation":0.85,"quality_attention":0.75,"support":0.55}'::jsonb),
('RTN004','A warmer hello','When you first see each other today, stop what you''re doing and greet them with a form of touch that is already normal and welcome between you. Let it last one extra beat.','A familiar hello can become invisible. Giving it a little more warmth makes the reunion feel intentional again.','DO',ARRAY['attention','perceived_responsiveness']::text[],ARRAY['home','cafe_or_bar','restaurant','anywhere']::text[],1,1,false,true,'high','high','{"routine":1,"closeness":0.7}'::jsonb,ARRAY[1,4]::integer[],ARRAY['touch_not_welcome']::text[],'{"physical_affection":1,"quality_attention":0.6,"verbal_affection":0.3}'::jsonb),
('RTN005','Catch the story','Catch one annoyed thought about your partner today. Name the story your mind is telling you before you react.','The first explanation in your head is not always the only one. Catching it gives you room to choose your response.','NOTICE',ARRAY['self_monitoring','alternative_interpretation']::text[],ARRAY['home','car','shopping_or_errands','anywhere']::text[],1,1,false,false,'high','medium','{"routine":0.8,"conflict":0.8,"communication":0.5}'::jsonb,ARRAY[1,3]::integer[],ARRAY['acute_conflict']::text[],'{"emotional_conversation":0.45,"support":0.25}'::jsonb),
('RTN006','Find one detail','Notice one detail about your partner you haven''t paid attention to lately: their clothes, expression, music, food choice, or something they''re absorbed in.','Familiarity can narrow attention. Deliberately noticing detail makes the familiar visible again.','NOTICE',ARRAY['attention','curiosity']::text[],ARRAY['home','outdoors','social_setting','anywhere']::text[],1,1,false,false,'medium','low','{"routine":1,"closeness":0.5}'::jsonb,ARRAY[1]::integer[],ARRAY[]::text[],'{"curiosity":1,"emotional_conversation":0.35,"quality_attention":0.9}'::jsonb),
('RTN007','Ask beyond logistics','Ask your partner one question today that has nothing to do with schedules, chores, money, food, or plans.','A question outside logistics gives you something to talk about besides managing the day.','DO',ARRAY['curiosity','self_disclosure']::text[],ARRAY['home','walking','cafe_or_bar','car','text_or_remote']::text[],2,1,false,true,'medium','medium','{"routine":0.9,"communication":0.7,"closeness":0.7}'::jsonb,ARRAY[1]::integer[],ARRAY['high_conflict']::text[],'{"curiosity":1,"emotional_conversation":0.9}'::jsonb),
('RTN008','Catch the bid','Catch one brief attempt your partner makes to connect: a joke, photo, comment, question, or look. Give it a real response.','Connection often starts in brief moments. Responding tells your partner that their attempt reached you.','DO',ARRAY['attention','perceived_responsiveness','positive_affect']::text[],ARRAY['home','text_or_remote','anywhere']::text[],2,1,false,true,'high','high','{"routine":0.9,"closeness":0.8,"communication":0.5}'::jsonb,ARRAY[1,4]::integer[],ARRAY[]::text[],'{"anticipation":0.25,"playfulness":0.75,"quality_attention":0.9,"support":0.55}'::jsonb),
('RTN009','Remember what drew you in','Bring to mind one thing that first drew you to your partner. Tell them, or simply carry it with you the next time you see them.','Remembering what first attracted you can bring back a version of your partner that daily logistics often hide.','NOTICE',ARRAY['attention','positive_affect']::text[],ARRAY['home','commuting','workday','anywhere']::text[],1,1,false,false,'medium','low','{"routine":0.8,"spark":0.7,"closeness":0.6}'::jsonb,ARRAY[1]::integer[],ARRAY['acute_conflict']::text[],'{"anticipation":0.25,"playfulness":0.75,"quality_attention":0.9,"verbal_affection":0.45}'::jsonb),
('RTN010','Five minutes, no admin','Spend five minutes together without talking about chores, schedules, work admin, or tomorrow''s plans.','Briefly removing logistical talk creates room for a different kind of interaction.','TRY_DIFFERENTLY',ARRAY['behavioral_experiment','environmental_design','shared_activity']::text[],ARRAY['home','walking','car','cafe_or_bar']::text[],5,1,false,true,'medium','medium','{"routine":1,"closeness":0.6,"communication":0.4}'::jsonb,ARRAY[1,2]::integer[],ARRAY['urgent_logistics']::text[],'{"shared_experience":1,"spontaneity":0.35}'::jsonb),
('RTN011','Take a new route','Take a walk together and choose streets you''ve never walked down before. No destination needed. Just explore for ten minutes.','A different route gives you something new to notice together without needing a plan.','TRY_DIFFERENTLY',ARRAY['novelty','behavioral_experiment','environmental_design']::text[],ARRAY['walking','car','outdoors','shopping_or_errands']::text[],5,1,false,true,'medium','medium','{"routine":1,"spark":0.5}'::jsonb,ARRAY[2]::integer[],ARRAY['mobility_constraints']::text[],'{"anticipation":0.35,"novelty":1,"shared_experience":0.2,"spontaneity":0.65}'::jsonb),
('RTN012','Choose for each other','Get a coffee, snack, or treat together and choose for each other. Keep it within things you already know the other person likes.','A low-stakes change to a familiar choice introduces novelty and attention without requiring a special date.','TRY_DIFFERENTLY',ARRAY['novelty','curiosity','behavioral_experiment']::text[],ARRAY['cafe_or_bar','restaurant','shopping_or_errands']::text[],5,2,false,true,'low','low','{"routine":0.9,"spark":0.7}'::jsonb,ARRAY[2]::integer[],ARRAY['dietary_or_financial_constraints']::text[],'{"anticipation":0.35,"curiosity":1,"emotional_conversation":0.35,"novelty":1,"spontaneity":0.65}'::jsonb),
('RTN013','Send the unexpected thing','Send them something during the day that isn''t practical: a photo, thought, joke, or something that made you think of them.','Changing a communication channel from coordination to connection adds novelty to an ordinary day.','DO',ARRAY['positive_affect','approach_behavior','attention']::text[],ARRAY['workday','commuting','text_or_remote']::text[],2,1,false,false,'high','medium','{"routine":0.8,"spark":0.5,"closeness":0.6}'::jsonb,ARRAY[2]::integer[],ARRAY['acute_conflict']::text[],'{"anticipation":0.25,"playfulness":0.75,"quality_attention":0.9,"shared_experience":0.5,"verbal_affection":0.3}'::jsonb),
('RTN014','Hand over one choice','Give your partner one choice you usually make today: the music, route, show, dinner, or where you sit. Go with their pick.','Letting them choose changes the usual rhythm and gives you a chance to follow instead of lead.','TRY_DIFFERENTLY',ARRAY['behavioral_experiment','novelty','response_substitution']::text[],ARRAY['home','car','restaurant','anywhere']::text[],2,1,false,true,'medium','medium','{"routine":1,"fairness":0.4}'::jsonb,ARRAY[2]::integer[],ARRAY[]::text[],'{"anticipation":0.35,"emotional_conversation":0.25,"novelty":1,"spontaneity":0.65}'::jsonb),
('RTN015','Unexpected favor','Do one useful or enjoyable thing they aren''t expecting today. Keep it easy enough that it doesn''t create an obligation to react.','An unexpected favor says ''I was thinking about you'' without asking for anything back.','DO',ARRAY['novelty','appreciation','support']::text[],ARRAY['home','workday','shopping_or_errands','anywhere']::text[],5,2,false,false,'medium','medium','{"routine":0.9,"spark":0.6,"support":0.7}'::jsonb,ARRAY[2]::integer[],ARRAY['resentment_or_scorekeeping']::text[],'{"anticipation":0.35,"appreciation":1,"novelty":1,"spontaneity":0.65,"support":1,"verbal_affection":0.35}'::jsonb),
('RTN016','Try their pick','Choose one low-stakes thing your partner likes that you usually wouldn''t pick: a song, snack, short video, route, or activity. Join them in it once.','Joining something they like lets you meet them inside their world for a moment.','TRY_DIFFERENTLY',ARRAY['approach_behavior','novelty','shared_activity']::text[],ARRAY['home','outdoors','cafe_or_bar','text_or_remote']::text[],10,2,false,true,'medium','low','{"routine":0.9,"spark":0.6,"closeness":0.5}'::jsonb,ARRAY[2]::integer[],ARRAY[]::text[],'{"anticipation":0.35,"novelty":1,"shared_experience":1,"spontaneity":0.65}'::jsonb),
('RTN017','Add ten minutes','Turn one errand together into ten extra minutes. Walk another block, sit somewhere, or wander into a place you''ve never stopped at.','Adding time to something you already had to do creates shared time without planning a separate date.','TRY_DIFFERENTLY',ARRAY['behavioral_activation','shared_activity','cue_association','novelty']::text[],ARRAY['shopping_or_errands','walking','outdoors']::text[],10,2,false,true,'high','high','{"routine":1,"spark":0.5,"closeness":0.5}'::jsonb,ARRAY[2,4]::integer[],ARRAY['time_pressure']::text[],'{"anticipation":0.35,"novelty":1,"shared_experience":1,"spontaneity":0.65}'::jsonb),
('RTN018','Sit a little closer','During one ordinary moment together, sit close enough for comfortable contact for a minute. Use the kind of closeness that is already normal and welcome between you.','Familiar, welcome touch can add warmth to an ordinary moment without turning it into a big gesture.','TRY_DIFFERENTLY',ARRAY['environmental_design','novelty']::text[],ARRAY['home','cafe_or_bar','restaurant','outdoors']::text[],1,1,false,true,'medium','medium','{"routine":1,"spark":0.4}'::jsonb,ARRAY[2]::integer[],ARRAY['touch_not_welcome']::text[],'{"physical_affection":1,"quality_attention":0.3,"shared_experience":0.4}'::jsonb),
('RTN019','Bring back a song','Play one song connected to a good shared memory while you''re together or send it to them without a long explanation.','A song tied to a good memory can bring the feeling of that memory into an ordinary day.','DO',ARRAY['positive_affect','cue_association']::text[],ARRAY['home','car','walking','text_or_remote']::text[],4,1,false,false,'high','high','{"routine":0.7,"spark":0.8,"closeness":0.6}'::jsonb,ARRAY[2,4]::integer[],ARRAY['painful_memory_association']::text[],'{"anticipation":0.45,"playfulness":0.75,"verbal_affection":0.45}'::jsonb),
('RTN020','Let the phone wait','Choose one ordinary five-minute moment together today and leave your phone out of reach until the moment is over.','Putting the phone out of reach makes attention easier because you do not have to keep choosing against it.','TRY_DIFFERENTLY',ARRAY['environmental_design','attention','behavioral_experiment']::text[],ARRAY['home','cafe_or_bar','restaurant','car']::text[],5,1,false,false,'high','high','{"routine":0.9,"closeness":0.6,"communication":0.4}'::jsonb,ARRAY[2,4]::integer[],ARRAY['on_call_or_urgent_contact']::text[],'{"quality_attention":0.9,"shared_experience":0.2,"spontaneity":0.35}'::jsonb),
('RTN021','Invite them along','Invite your partner into one thing you''d normally do alone today: a walk, shop run, coffee, cooking, or quick errand.','An invitation turns an existing routine into an opportunity for shared activity without adding much effort.','DO',ARRAY['approach_behavior','shared_activity']::text[],ARRAY['home','walking','shopping_or_errands','cafe_or_bar']::text[],10,2,false,true,'high','high','{"routine":1,"closeness":0.6}'::jsonb,ARRAY[2,4]::integer[],ARRAY['need_for_space']::text[],'{"anticipation":0.25,"shared_experience":1}'::jsonb),
('RTN022','Say what you still like','Tell your partner one thing you still like about who they are. Make it about them, not a chore or favor they did.','Being valued for who you are feels different from being thanked for what you do.','DO',ARRAY['appreciation','positive_affect','perceived_responsiveness']::text[],ARRAY['home','walking','text_or_remote','anywhere']::text[],1,1,false,false,'medium','medium','{"routine":0.9,"closeness":0.8}'::jsonb,ARRAY[2]::integer[],ARRAY['acute_conflict']::text[],'{"appreciation":0.7,"quality_attention":0.4,"verbal_affection":1}'::jsonb),
('RTN023','Reverse one role','For one routine today, swap who normally does it or who takes the lead.','Swapping a familiar role can show you what the other person normally carries without much discussion.','TRY_DIFFERENTLY',ARRAY['behavioral_experiment','response_substitution','fairness']::text[],ARRAY['home','shopping_or_errands','anywhere']::text[],10,2,false,true,'medium','medium','{"routine":0.8,"fairness":0.8}'::jsonb,ARRAY[2]::integer[],ARRAY['high_conflict_about_chore']::text[],'{"appreciation":0.2,"emotional_conversation":0.25,"spontaneity":0.35,"support":0.35}'::jsonb),
('RTN024','Ask for a micro-adventure','Offer two easy options that are different from the usual: walk after dinner or dessert outside, new café or old favorite. Let them pick.','Constrained choices make novelty easier to act on than vague plans to ''do more together.''','DO',ARRAY['novelty','shared_activity','environmental_design']::text[],ARRAY['home','outdoors','cafe_or_bar','date_or_night_out']::text[],15,2,true,true,'medium','medium','{"routine":0.9,"spark":0.7}'::jsonb,ARRAY[2]::integer[],ARRAY['time_or_money_pressure']::text[],'{"anticipation":0.7,"novelty":1,"shared_experience":1,"spontaneity":0.65}'::jsonb),
('RTN025','Change the first minute','Pick one recurring moment today: waking up, coming home, dinner, getting into the car. Deliberately change only its first minute.','Changing the first minute can stop the rest of a familiar moment from running exactly the usual way.','TRY_DIFFERENTLY',ARRAY['cue_association','response_substitution','behavioral_experiment']::text[],ARRAY['home','car','anywhere']::text[],1,1,false,false,'high','high','{"routine":1,"communication":0.4}'::jsonb,ARRAY[2,3,4]::integer[],ARRAY[]::text[],'{"anticipation":0.2,"emotional_conversation":0.25,"spontaneity":0.35}'::jsonb),
('RTN026','Add one playful choice','Turn one boring decision today into a playful one: coin flip the takeaway, each pick a mystery snack, or choose the next song for each other.','A playful choice gives an ordinary decision a different energy.','TRY_DIFFERENTLY',ARRAY['positive_affect','novelty','behavioral_experiment']::text[],ARRAY['home','shopping_or_errands','car','cafe_or_bar']::text[],3,1,false,true,'medium','medium','{"routine":0.8,"spark":0.7}'::jsonb,ARRAY[2]::integer[],ARRAY[]::text[],'{"anticipation":0.35,"novelty":1,"playfulness":1,"spontaneity":0.65}'::jsonb),
('RTN027','Pause one beat','Take one breath before answering the first time you feel a sharp, dismissive, or impatient reply coming.','One breath is often enough to stop the first sharp reply from deciding the rest of the exchange.','TRY_DIFFERENTLY',ARRAY['pause_before_response','response_substitution']::text[],ARRAY['home','car','text_or_remote','anywhere']::text[],1,1,false,false,'high','high','{"routine":0.8,"conflict":0.9,"communication":0.7}'::jsonb,ARRAY[3,4]::integer[],ARRAY['unsafe_or_escalating_conflict']::text[],'{"emotional_conversation":0.35,"support":0.25}'::jsonb),
('RTN028','What else could it mean?','Catch one moment when you decide what your partner meant. Ask yourself, “What else could this mean?” before responding.','The first meaning you give a comment is not always the only one. Another plausible reading can change your next response.','NOTICE',ARRAY['alternative_interpretation','pause_before_response']::text[],ARRAY['home','workday','text_or_remote','anywhere']::text[],1,1,false,false,'high','high','{"routine":0.7,"conflict":0.9,"communication":0.7}'::jsonb,ARRAY[3,4]::integer[],ARRAY['clear_boundary_violation']::text[],'{"emotional_conversation":0.35,"support":0.25}'::jsonb),
('RTN029','Finish hearing it','Let your partner fully finish one story or point today before you start preparing your answer.','Letting them finish makes listening the main task for a moment, rather than preparing your reply.','TRY_DIFFERENTLY',ARRAY['active_listening','attention','response_substitution']::text[],ARRAY['home','walking','car','text_or_remote']::text[],3,1,false,true,'high','high','{"routine":0.7,"communication":1,"closeness":0.5}'::jsonb,ARRAY[3,4]::integer[],ARRAY[]::text[],'{"emotional_conversation":1,"quality_attention":0.9}'::jsonb),
('RTN030','Answer the feeling first','Respond to the feeling first when your partner tells you about something frustrating today. Leave advice and fixing for later.','People often want to feel understood before they want a solution.','TRY_DIFFERENTLY',ARRAY['perceived_responsiveness','validation','response_substitution']::text[],ARRAY['home','walking','text_or_remote','anywhere']::text[],2,1,false,true,'high','high','{"routine":0.7,"communication":0.9,"support":0.8}'::jsonb,ARRAY[3,4]::integer[],ARRAY['explicit_request_for_solution']::text[],'{"emotional_conversation":0.45,"quality_attention":0.55,"support":1}'::jsonb),
('RTN031','Say it softer','Say one difficult point in a calmer first sentence today. Keep the point; change the delivery.','Changing delivery while keeping the underlying need intact tests whether the interaction pattern can shift without avoidance.','TRY_DIFFERENTLY',ARRAY['response_substitution','behavioral_experiment','repair']::text[],ARRAY['home','car','anywhere']::text[],2,2,false,true,'medium','medium','{"routine":0.6,"conflict":1,"communication":0.8}'::jsonb,ARRAY[3]::integer[],ARRAY['unsafe_or_high_intensity_conflict']::text[],'{"emotional_conversation":0.5,"spontaneity":0.35,"support":0.75}'::jsonb),
('RTN032','Repair the miss','Repair one miss as soon as you notice it. Say, “That came out wrong,” or “Sorry, I wasn''t listening,” and try the moment again.','A quick repair can stop one bad moment from becoming the tone of the next ten minutes.','DO',ARRAY['repair','perceived_responsiveness']::text[],ARRAY['home','workday','text_or_remote','anywhere']::text[],1,1,false,true,'high','high','{"routine":0.7,"conflict":0.8,"communication":0.8}'::jsonb,ARRAY[3,4]::integer[],ARRAY['unsafe_conflict']::text[],'{"emotional_conversation":0.5,"quality_attention":0.55,"support":0.9}'::jsonb),
('RTN033','Make one clean request','Turn one “Why do you always...?” thought into a concrete request about what you need right now.','A specific request reduces mind-reading and global judgments while preserving the underlying need.','TRY_DIFFERENTLY',ARRAY['response_substitution','behavioral_experiment']::text[],ARRAY['home','text_or_remote','anywhere']::text[],2,2,false,true,'medium','medium','{"routine":0.6,"communication":0.9,"conflict":0.9}'::jsonb,ARRAY[3]::integer[],ARRAY['unsafe_or_coercive_context']::text[],'{"emotional_conversation":0.25,"spontaneity":0.35}'::jsonb),
('RTN034','Drop the scoreboard once','Catch yourself mentally counting who did more once today. Decide what you need, then ask for it plainly or let this one go.','Moving from internal scorekeeping to a specific choice interrupts resentment-building without denying genuine imbalance.','TRY_DIFFERENTLY',ARRAY['self_monitoring','response_substitution','behavioral_experiment']::text[],ARRAY['home','shopping_or_errands','anywhere']::text[],2,2,false,false,'medium','medium','{"routine":0.6,"fairness":0.9,"communication":0.6}'::jsonb,ARRAY[3]::integer[],ARRAY['persistent_or_serious_inequity']::text[],'{"emotional_conversation":0.25,"spontaneity":0.35}'::jsonb),
('RTN035','Try one generous reading','Choose one ambiguous thing your partner does today and give it the most reasonable non-hostile explanation that fits the facts.','When intent is unclear, a reasonable reading can stop an assumption from turning into a fight.','TRY_DIFFERENTLY',ARRAY['alternative_interpretation','behavioral_experiment']::text[],ARRAY['home','workday','text_or_remote','anywhere']::text[],1,1,false,false,'medium','medium','{"routine":0.6,"conflict":0.8,"trust":0.5}'::jsonb,ARRAY[3]::integer[],ARRAY['clear_harm_or_boundary_violation']::text[],'{"spontaneity":0.35}'::jsonb),
('RTN036','Turn toward','Give your partner your full attention for ten seconds the next time they show you something or make a brief comment. Then return to what you were doing.','Giving one moment your full attention makes it clear that what they said reached you.','DO',ARRAY['perceived_responsiveness','attention','response_substitution']::text[],ARRAY['home','workday','anywhere']::text[],1,1,false,true,'high','high','{"routine":0.9,"closeness":0.8,"communication":0.5}'::jsonb,ARRAY[3,4]::integer[],ARRAY['urgent_task']::text[],'{"emotional_conversation":0.25,"quality_attention":0.9,"support":0.55}'::jsonb),
('RTN037','Ask before fixing','Ask, “Do you want ideas or do you want me to listen?” the first time your partner brings you a problem today.','A simple choice interrupts habitual fixing and makes support more responsive to what is actually wanted.','TRY_DIFFERENTLY',ARRAY['active_listening','support','behavioral_experiment']::text[],ARRAY['home','walking','text_or_remote','anywhere']::text[],1,1,false,true,'high','high','{"routine":0.6,"communication":0.9,"support":1}'::jsonb,ARRAY[3,4]::integer[],ARRAY[]::text[],'{"emotional_conversation":0.85,"quality_attention":0.75,"spontaneity":0.35,"support":1}'::jsonb),
('RTN038','Reset outside','Take a ten-minute walk together when the mood at home feels stuck. Leave the problem indoors for the first five minutes.','A change of setting can loosen a mood that has started to feel stuck.','TRY_DIFFERENTLY',ARRAY['environmental_design','behavioral_experiment','shared_activity']::text[],ARRAY['home','walking','outdoors']::text[],10,2,true,true,'medium','medium','{"routine":0.8,"conflict":0.5,"closeness":0.5}'::jsonb,ARRAY[3]::integer[],ARRAY['unsafe_conflict_or_mobility_constraints']::text[],'{"shared_experience":1,"spontaneity":0.35}'::jsonb),
('RTN039','A warmer goodbye','Before one separation today, add a form of affection that is already normal and welcome between you. Make it intentional instead of automatic.','Goodbyes happen often enough to become invisible. Making one warmer gives that transition some attention again.','DO',ARRAY['cue_association','attention','positive_affect']::text[],ARRAY['home','workday','commuting','travel']::text[],1,1,false,true,'high','high','{"routine":0.9,"closeness":0.7}'::jsonb,ARRAY[3,4]::integer[],ARRAY['touch_not_welcome']::text[],'{"physical_affection":1,"quality_attention":0.4,"verbal_affection":0.45}'::jsonb),
